import pyomo.environ as pyo

DATA = {
    "products": [0, 1, 2],
    "months": [0, 1, 2, 3, 4, 5],
    "cum_demand": {
        0: [75, 141, 241, 315, 386, 469],
        1: [65, 151, 228, 286, 338, 390],
        2: [57, 143, 193, 263, 363, 428],
    },
    "cost_prod": {
        0: [42, 47, 41, 40, 43, 47],
        1: [43, 50, 41, 50, 49, 46],
        2: [42, 49, 40, 47, 49, 45],
    },
    "cost_setup": {
        0: [1282, 1493, 1006, 1286, 1305, 1360],
        1: [1402, 1498, 1296, 1366, 1376, 1172],
        2: [1362, 1094, 1283, 1279, 1430, 1146],
    },
    "cost_hold": {
        0: [4, 5, 4, 5, 4, 4],
        1: [5, 5, 5, 4, 4, 4],
        2: [5, 5, 4, 5, 5, 4],
    },
    "capacity": [1173, 1102, 1018, 1077, 1190, 1132],
    "usage": {0: 1.778, 1: 1.502, 2: 1.556},
    "upper": {
        0: [469, 394, 328, 228, 154, 83],
        1: [390, 325, 239, 162, 104, 52],
        2: [428, 371, 285, 235, 165, 65],
    },
}


def build_model(data=None):
    d = data or DATA
    P = d["products"]
    M = d["months"]

    demand = {}
    for p in P:
        cum = d["cum_demand"][p]
        demand[p] = [cum[0]] + [cum[m] - cum[m - 1] for m in range(1, len(cum))]

    model = pyo.ConcreteModel()
    model.P = pyo.Set(initialize=P)
    model.M = pyo.Set(initialize=M, ordered=True)

    model.prod = pyo.Var(model.P, model.M, within=pyo.NonNegativeIntegers)
    model.setup = pyo.Var(model.P, model.M, within=pyo.Binary)
    model.inv = pyo.Var(model.P, model.M, within=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return (
            sum(d["cost_prod"][p][t] * m.prod[p, t] for p in P for t in M)
            + sum(d["cost_setup"][p][t] * m.setup[p, t] for p in P for t in M)
            + sum(d["cost_hold"][p][t] * m.inv[p, t] for p in P for t in M)
        )
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def balance_rule(m, p, t):
        prev = 0 if t == M[0] else m.inv[p, t - 1]
        return prev + m.prod[p, t] - m.inv[p, t] == demand[p][t]
    model.balance = pyo.Constraint(model.P, model.M, rule=balance_rule)

    def demand_rule(m, p, t):
        return sum(m.prod[p, s] for s in M if s <= t) >= d["cum_demand"][p][t]
    model.demand_sat = pyo.Constraint(model.P, model.M, rule=demand_rule)

    def final_inv_rule(m, p):
        return m.inv[p, M[-1]] == 0
    model.final_inv = pyo.Constraint(model.P, rule=final_inv_rule)

    def setup_rule(m, p, t):
        return m.prod[p, t] <= d["upper"][p][t] * m.setup[p, t]
    model.setup_link = pyo.Constraint(model.P, model.M, rule=setup_rule)

    def capacity_rule(m, t):
        return sum(d["usage"][p] * m.prod[p, t] for p in P) <= d["capacity"][t]
    model.capacity = pyo.Constraint(model.M, rule=capacity_rule)

    return model


